create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles(id) on delete cascade,name text not null,code text,status text not null default 'active',project_type text not null,address text,progress numeric(5,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists workers(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,phone text,specialty text,payment_type text,daily_wage numeric(14,2),hourly_wage numeric(14,2),overtime_rate numeric(14,2),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists contractors(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,phone text,specialty text,unit text,unit_rate numeric(14,2),created_at timestamptz not null default now());
create table if not exists materials(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,unit text not null,current_stock numeric(14,3) not null default 0,reorder_point numeric(14,3) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists daily_reports(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,report_date date not null,notes text,status text not null default 'draft',created_by uuid references profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,report_date));
create table if not exists alerts(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,type text not null,message text not null,status text not null default 'open',created_at timestamptz not null default now());
create or replace function public.is_project_member(p_project_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from projects where id=p_project_id and owner_id=auth.uid()) $$;
alter table profiles enable row level security; alter table projects enable row level security; alter table workers enable row level security; alter table contractors enable row level security; alter table materials enable row level security; alter table daily_reports enable row level security; alter table alerts enable row level security;
create policy "own profile" on profiles for all using(id=auth.uid()) with check(id=auth.uid()); create policy "own projects" on projects for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "project workers" on workers for all using(is_project_member(project_id)) with check(is_project_member(project_id)); create policy "project contractors" on contractors for all using(is_project_member(project_id)) with check(is_project_member(project_id)); create policy "project materials" on materials for all using(is_project_member(project_id)) with check(is_project_member(project_id)); create policy "project reports" on daily_reports for all using(is_project_member(project_id)) with check(is_project_member(project_id)); create policy "project alerts" on alerts for all using(is_project_member(project_id)) with check(is_project_member(project_id));